1	/**
2	 * ActiveJobs Feature — Type Definitions
3	 *
4	 * Tasks can require acknowledgment (agent-decided). Tasks that require it
5	 * persist in the UI until manually dismissed. Others auto-dismiss.
6	 */
7	
8	export type TaskStatus = "running" | "done" | "failed";
9	
10	export interface Task {
11	  id: string;
12	  /** Display name shown in the clean card view */
13	  name: string;
14	  /** Two-sentence description: what the agent is doing + what it's investigating/building */
15	  description?: string;
16	  status: TaskStatus;
17	  /**
18	   * Agent decides whether the task needs human review.
19	   *
20	   * true  → task persists until user manually dismisses (code changes, UI work, bug fixes, config)
21	   * false → task auto-dismisses after completion (reads, searches, status checks, info retrieval)
22	   *
23	   * Default: true (safer — assume review needed unless explicitly marked otherwise)
24	   */
25	  requiresAcknowledgment: boolean;
26	
27	  // ── Metadata (shown behind ℹ️ info panel) ──
28	  model?: string;
29	  startedAt: string; // ISO timestamp
30	  source?: string; // e.g. "Discord", "Voice", "Web"
31	  tokens?: number;
32	  sessionId?: string;
33	  /** Any extra key-value metadata the agent wants to surface */
34	  meta?: Record<string, string>;
35	}
36	
37	/** Duration helper — returns human-readable duration from ISO start time */
38	export function formatDuration(startedAt: string): string {
39	  const ms = Date.now() - new Date(startedAt).getTime();
40	  if (ms < 0) return "0s";
41	  const seconds = Math.floor(ms / 1000);
42	  if (seconds < 60) return `${seconds}s`;
43	  const minutes = Math.floor(seconds / 60);
44	  const remainingSeconds = seconds % 60;
45	  if (minutes < 60) return `${minutes}m ${remainingSeconds}s`;
46	  const hours = Math.floor(minutes / 60);
47	  const remainingMinutes = minutes % 60;
48	  return `${hours}h ${remainingMinutes}m`;
49	}
50	
51	/** Format token count with commas */
52	export function formatTokens(tokens: number): string {
53	  return tokens.toLocaleString();
54	}
55

