1	"use client";
2	
3	import { useState, useCallback, useEffect, useRef } from "react";
4	import type { Task } from "./types";
5	import { useSessionPolling } from "./useSessionPolling";
6	
7	/** Auto-dismiss delay for tasks that don't require acknowledgment (ms) */
8	const AUTO_DISMISS_DELAY = 3000;
9	
10	export interface ActiveJobsState {
11	  tasks: Task[];
12	  expandedIds: Set<string>;
13	  addTask: (task: Task) => void;
14	  updateTask: (id: string, patch: Partial<Task>) => void;
15	  dismissTask: (id: string) => void;
16	  toggleExpanded: (id: string) => void;
17	}
18	
19	export function useActiveJobs(): ActiveJobsState {
20	  // Manual tasks (added via addTask)
21	  const [manualTasks, setManualTasks] = useState<Task[]>([]);
22	  
23	  // Auto-discovered tasks from session polling
24	  const { tasks: polledTasks } = useSessionPolling(true);
25	  
26	  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
27	  const autoDismissTimers = useRef<Map<string, NodeJS.Timeout>>(new Map());
28	  
29	  // Dismissed task IDs (to prevent re-showing completed sub-agents)
30	  const [dismissedIds, setDismissedIds] = useState<Set<string>>(new Set());
31	  
32	  // Merge manual and polled tasks, filter dismissed
33	  const tasks = [...manualTasks, ...polledTasks].filter(
