1	'use client';
2	
3	import { useState, useCallback } from 'react';
4	
5	export interface TaskFeedback {
6	  taskId: string;
7	  taskName: string;
8	  type: 'up' | 'down';
9	  notes: string;
10	  images: File[];
11	  timestamp: number;
12	  mode: 'text' | 'voice';
13	  /** Original task description for relaunch context */
14	  taskDescription?: string;
15	}
16	
17	export interface FeedbackState {
18	  /** Map of taskId → feedback type already submitted */
19	  submitted: Map<string, 'up' | 'down'>;
20	}
21	
22	export function useTaskFeedback() {
23	  const [feedbackState, setFeedbackState] = useState<FeedbackState>({
24	    submitted: new Map(),
25	  });
26	  /** Which task ID currently has inline feedback open (null = none) */
27	  const [inlineFeedbackTaskId, setInlineFeedbackTaskId] = useState<string | null>(null);
28	  const [inlineFeedbackTaskName, setInlineFeedbackTaskName] = useState<string>('');
29	  const [submitting, setSubmitting] = useState(false);
30	
31	  const handleThumbsUp = useCallback(async (taskId: string, taskName: string) => {
32	    setFeedbackState((prev) => {
33	      const next = new Map(prev.submitted);
34	      next.set(taskId, 'up');
35	      return { submitted: next };
36	    });
37	
38	    try {
39	      await fetch('/api/task-feedback', {
40	        method: 'POST',
41	        headers: { 'Content-Type': 'application/json' },
42	        body: JSON.stringify({
43	          taskId,
44	          taskName,
45	          type: 'up',
46	          notes: '',
47	          images: [],
48	          timestamp: Date.now(),
49	          mode: 'text',
50	        }),
51	      });
52	    } catch (e) {
53	      console.error('Failed to submit thumbs up feedback:', e);
54	    }
55	  }, []);
56	
57	  /** Toggle inline feedback for a specific task (replaces modal) */
58	  const openInlineFeedback = useCallback((taskId: string, taskName: string) => {
59	    setInlineFeedbackTaskId((prev) => (prev === taskId ? null : taskId));
60	    setInlineFeedbackTaskName(taskName);
61	  }, []);
62	
63	  const closeInlineFeedback = useCallback(() => {
64	    setInlineFeedbackTaskId(null);
65	    setInlineFeedbackTaskName('');
66	  }, []);
67	
68	  const submitFeedback = useCallback(async (feedback: TaskFeedback) => {
69	    setSubmitting(true);
70	    try {
71	      const formData = new FormData();
72	      formData.append('taskId', feedback.taskId);
73	      formData.append('taskName', feedback.taskName);
74	      formData.append('type', feedback.type);
75	      formData.append('notes', feedback.notes);
76	      formData.append('timestamp', String(feedback.timestamp));
77	      formData.append('mode', feedback.mode);
78	      if (feedback.taskDescription) {
79	        formData.append('taskDescription', feedback.taskDescription);
80	      }
81	      // Request relaunch when negative feedback
82	      formData.append('relaunch', 'true');
83	      for (const img of feedback.images) {
84	        formData.append('images', img);
85	      }
86	
87	      await fetch('/api/task-feedback', {
88	        method: 'POST',
89	        body: formData,
90	      });
91	
92	      setFeedbackState((prev) => {
93	        const next = new Map(prev.submitted);
94	        next.set(feedback.taskId, 'down');
95	        return { submitted: next };
96	      });
97	
98	      closeInlineFeedback();
99	    } catch (e) {
100	      console.error('Failed to submit feedback:', e);
101	    } finally {
102	      setSubmitting(false);
103	    }
104	  }, [closeInlineFeedback]);
105	
106	  return {
107	    feedbackState,
108	    inlineFeedbackTaskId,
109	    inlineFeedbackTaskName,
110	    submitting,
111	    handleThumbsUp,
112	    openInlineFeedback,
113	    closeInlineFeedback,
114	    submitFeedback,
115	  };
116	}
117

