1	"use client";
2	
3	import { useState, useEffect, useCallback, useRef } from "react";
4	import type { Task } from "./types";
5	
6	interface SessionInfo {
7	  sessionId: string;
8	  agent: string;
9	  label?: string;
10	  description?: string;
11	  startedAt?: string;
12	  isSubagent: boolean;
13	}
14	
15	interface SessionsResponse {
16	  sessions: SessionInfo[];
17	}
18	
19	/**
20	 * Poll the /api/sessions endpoint and convert sessions to Tasks.
21	 *
22	 * Only sub-agent sessions become tasks — main sessions are ignored.
23	 * Polling interval: 2 seconds (adjustable).
24	 */
25	export function useSessionPolling(enabled: boolean = true) {
26	  const [tasks, setTasks] = useState<Map<string, Task>>(new Map());
27	  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null);
28	  const [isPolling, setIsPolling] = useState(false);
29	  const tasksRef = useRef(tasks);
30	  tasksRef.current = tasks;
31	
32	  const fetchSessions = useCallback(async () => {
33	    if (!enabled) return;
34	
35	    try {
36	      const response = await fetch("/api/sessions");
37	      if (!response.ok) {
38	        console.warn("Failed to fetch sessions:", response.statusText);
39	        return;
40	      }
41	
42	      const data: SessionsResponse = await response.json();
43	      const prevTasks = tasksRef.current;
44	
45	      // Convert sub-agent sessions to tasks
46	      const newTasks = new Map<string, Task>();
47	
48	      for (const session of data.sessions) {
49	        // Only track sub-agents
50	        if (!session.isSubagent) continue;
51	
52	        const existingTask = prevTasks.get(session.sessionId);
53	
54	        // If task already exists and is completed, don't overwrite
55	        if (existingTask && existingTask.status !== "running") {
56	          newTasks.set(session.sessionId, existingTask);
57	          continue;
58	        }
59	
60	        // Create or update task
61	        const rawLabel = session.label || '';
62	        const isHexId = /^[0-9a-f]{6,}(-[0-9a-f]+)*$/i.test(rawLabel.replace(/^agent:main:subagent:/, ''));
63	        const taskName = (rawLabel && !isHexId) ? rawLabel : `Task (${session.agent})`;
64	        newTasks.set(session.sessionId, {
65	          id: session.sessionId,
66	          name: taskName,
67	          description: session.description,
68	          status: "running",
69	          requiresAcknowledgment: true, // Safe default — assume review needed
70	          startedAt: session.startedAt || new Date().toISOString(),
71	          model: session.agent,
72	          source: "Sub-agent",
73	          sessionId: session.sessionId,
74	        });
75	      }
76	
77	      // Mark tasks as completed if they're no longer in the sessions list
78	      prevTasks.forEach((task, id) => {
79	        if (!newTasks.has(id) && task.status === "running") {
80	          newTasks.set(id, {
81	            ...task,
82	            status: "done",
83	          });
84	        }
85	      });
86	
87	      setTasks(newTasks);
88	    } catch (error) {
89	      console.error("Session polling error:", error);
90	    }
91	  }, [enabled]);
92	
93	  useEffect(() => {
94	    if (!enabled) {
95	      if (pollIntervalRef.current) {
96	        clearInterval(pollIntervalRef.current);
97	        pollIntervalRef.current = null;
98	      }
99	      setIsPolling(false);
100	      return;
101	    }
102	
103	    // Initial fetch
104	    fetchSessions();
105	    setIsPolling(true);
106	
107	    // Poll every 2 seconds
108	    pollIntervalRef.current = setInterval(fetchSessions, 2000);
109	
110	    return () => {
111	      if (pollIntervalRef.current) {
112	        clearInterval(pollIntervalRef.current);
113	        pollIntervalRef.current = null;
114	      }
115	    };
116	  }, [enabled, fetchSessions]);
117	
118	  return {
119	    tasks: Array.from(tasks.values()),
120	    isPolling,
121	  };
122	}
