21	export function TaskCard({ task, expanded, onToggleExpanded, onDismiss }: TaskCardProps) {
22	  // Live duration ticker for running tasks
23	  const [, setTick] = useState(0);
24	  useEffect(() => {
25	    if (task.status !== "running") return;
26	    const id = setInterval(() => setTick((t) => t + 1), 1000);
