1	'use client';
2	
3	import { useEffect, useState } from 'react';
4	
5	interface TaskState {
6	  id: string;
7	  label: string;
8	  progress: number;
9	}
10	
11	export default function CanvasTaskProgress() {
12	  const [task, setTask] = useState<TaskState | null>(null);
13	  const [hiding, setHiding] = useState(false);
14	
15	  useEffect(() => {
16	    const onStart = (e: Event) => {
17	      const detail = (e as CustomEvent).detail;
18	      const payload = detail?.payload ?? detail;
19	      setTask({
20	        id: payload?.taskId ?? '',
21	        label: payload?.label ?? 'Loading...',
22	        progress: 5,
23	      });
24	      setHiding(false);
25	    };
26	
27	    const onProgress = (e: Event) => {
28	      const detail = (e as CustomEvent).detail;
29	      const payload = detail?.payload ?? detail;
30	      const progress = payload?.progress ?? 0;
31	      setTask((prev) => (prev ? { ...prev, progress } : null));
32	    };
33	
34	    const onComplete = (e: Event) => {
35	      setTask((prev) => (prev ? { ...prev, progress: 100 } : null));
36	      setHiding(true);
37	      setTimeout(() => {
38	        setTask(null);
39	        setHiding(false);
40	      }, 800);
41	    };
42	
43	    window.addEventListener('nia:canvas.task.start', onStart);
44	    window.addEventListener('nia:canvas.task.progress', onProgress);
45	    window.addEventListener('nia:canvas.task.complete', onComplete);
46	
47	    return () => {
48	      window.removeEventListener('nia:canvas.task.start', onStart);
49	      window.removeEventListener('nia:canvas.task.progress', onProgress);
50	      window.removeEventListener('nia:canvas.task.complete', onComplete);
51	    };
52	  }, []);
53	
54	  if (!task) return null;
55	
56	  return (
57	    <div
58	      className="canvas-task-progress"
59	      style={{
60	        position: 'fixed',
61	        bottom: 100,
62	        left: '50%',
63	        transform: 'translateX(-50%)',
64	        width: 'clamp(280px, 50vw, 400px)',
65	        height: 36,
66	        background: 'rgba(56, 189, 248, 0.12)',
67	        border: '1px solid rgba(56, 189, 248, 0.2)',
68	        borderRadius: 18,
69	        overflow: 'hidden',
70	        zIndex: 1000,
71	        transition: 'opacity 0.3s ease',
72	        display: 'flex',
73	        alignItems: 'center',
74	        backdropFilter: 'blur(12px)',
75	        opacity: hiding ? 0 : 1,
76	      }}
77	    >
78	      <div
79	        style={{
80	          position: 'absolute',
81	          left: 0,
82	          top: 0,
83	          bottom: 0,
84	          width: `${task.progress}%`,
85	          background: 'linear-gradient(90deg, rgba(52, 211, 153, 0.3), rgba(52, 211, 153, 0.5))',
86	          borderRadius: 18,
87	          transition: 'width 0.6s cubic-bezier(0.4, 0, 0.2, 1)',
88	        }}
89	      />
90	      <span
91	        style={{
92	          position: 'relative',
93	          zIndex: 1,
94	          padding: '0 16px',
95	          fontSize: 13,
96	          fontWeight: 500,
97	          color: 'rgba(255, 255, 255, 0.8)',
98	          letterSpacing: '0.02em',
99	          whiteSpace: 'nowrap',
100	        }}
101	      >
102	        {task.label}
103	      </span>
104	    </div>
105	  );
106	}
