1	/**
2	 * Exec task registry — automatic task tracking for shell exec calls.
3	 *
4	 * When Pearl (or any caller of the terminal exec API) runs a Claude CLI command,
5	 * the registry writes a session record that the ActiveJobs widget picks up via
6	 * `/api/openclaw/sessions`. The record uses the `agent:claude-code:pearl-exec:*`
7	 * key prefix so the existing KIND_MATCHERS route it to kind='claude-code'.
8	 *
9	 * Session store:   ~/.openclaw/agents/pearl-exec/sessions/sessions.json
10	 * Widget polls:    /api/openclaw/sessions (reads all agent dirs)
11	 */
12	
13	import { promises as fs } from 'fs';
14	import path from 'path';
15	import os from 'os';
16	import crypto from 'crypto';
17	
18	const AGENT_NAME = 'pearl-exec';
19	const SESSION_STORE = path.join(
20	  os.homedir(),
21	  '.openclaw',
22	  'agents',
23	  AGENT_NAME,
24	  'sessions',
25	  'sessions.json'
26	);
27	
28	type SessionRecord = {
29	  sessionId: string;
30	  label: string;
31	  displayName: string;
32	  task: string;
33	  description: string;
34	  channel: string;
35	  model: string;
36	  createdAt: number;
37	  updatedAt: number;
38	  status: 'running' | 'complete' | 'failed';
39	  exitCode?: number;
40	  spawnedBy: string;
41	};
42	
43	type SessionStore = Record<string, SessionRecord>;
44	
45	/**
46	 * Detects whether a shell command invokes the Claude CLI.
47	 * Matches standalone `claude`, `claude-code`, env-prefixed (`HOME=... claude`),
48	 * piped (`echo x | claude`), and subshell (`$(claude ...)`) invocations.
49	 * Intentionally avoids false positives on paths like `claudette` or `claude.log`.
50	 */
51	export function isClaudeCliCommand(command: string): boolean {
52	  if (!command) return false;
53	  // Word-boundary match for `claude` or `claude-code` as an executable token.
54	  // Allowed leading contexts: line start, whitespace, `;`, `&`, `|`, `(`, `$(`,
55	  // backtick, or env-var assignments (letters=value pattern handled by whitespace after).
56	  return /(^|[\s;&|`(])(claude-code|claude)(\s|$)/.test(command);
57	}
58	
59	/**
60	 * Derives a short, human-readable label from an arbitrary Claude CLI command.
61	 * Example:
62	 *   `HOME=/root claude --print "Build the project"` → `claude --print "Build the project"`
63	 *   trimmed to 80 chars.
64	 */
65	export function deriveLabel(command: string): string {
66	  const trimmed = command.trim();
67	  // Strip leading env-var assignments (VAR=value ...) before the binary.
68	  const withoutEnv = trimmed.replace(/^(\w+=[^\s]+\s+)+/, '');
69	  // Take up to the first redirection/pipe for the headline.
70	  const headline = withoutEnv.split(/[|>&;]/)[0].trim();
71	  return headline.length > 80 ? headline.slice(0, 77) + '...' : headline;
72	}
73	
74	// In-process mutex chain. Serializes read-modify-write to the session store
75	// within a single Next.js worker. Does not protect against cross-process races,
76	// which are acceptable for a best-effort task registry.
77	let writeChain: Promise<void> = Promise.resolve();
78	
79	async function withStoreLock<T>(fn: () => Promise<T>): Promise<T> {
80	  const next = writeChain.then(fn, fn);
81	  writeChain = next.then(
82	    () => undefined,
83	    () => undefined,
84	  );
85	  return next;
86	}
87	
88	async function readStore(): Promise<SessionStore> {
89	  try {
90	    const raw = await fs.readFile(SESSION_STORE, 'utf-8');
91	    return JSON.parse(raw) as SessionStore;
92	  } catch {
93	    return {};
94	  }
95	}
96	
97	async function writeStore(store: SessionStore): Promise<void> {
98	  await fs.mkdir(path.dirname(SESSION_STORE), { recursive: true });
99	  const tmp = SESSION_STORE + '.tmp';
100	  await fs.writeFile(tmp, JSON.stringify(store, null, 2), 'utf-8');
101	  await fs.rename(tmp, SESSION_STORE);
102	}
103	
104	function makeTaskId(): string {
105	  // UUID-like id for the session key tail; short to keep keys readable.
106	  return crypto.randomBytes(8).toString('hex');
107	}
108	
109	export type RegisterOptions = {
110	  command: string;...

