1	import { NextResponse } from 'next/server';
2	import { readFile, readdir } from 'fs/promises';
3	import path from 'path';
4	
5	export const dynamic = 'force-dynamic';
6	export const revalidate = 0;
7	
8	interface ActiveJob {
9	  id: string;
10	  key: string;
11	  label: string;
12	  description: string;
13	  status: 'running' | 'complete' | 'idle';
14	  channel: string;
15	  model: string;
16	  startedAt: number;
17	  updatedAt: number;
18	  elapsedMs: number;
19	  displayName: string;
20	  totalTokens: number;
21	  kind: string;
22	  agents: string[];
23	}
24	
25	// Dynamically discover all agent session stores
26	const AGENTS_DIR = path.join(process.env.HOME || '/root', '.openclaw/agents');
27	
28	async function getSessionStorePaths(): Promise<string[]> {
29	  try {
30	    const agents = await readdir(AGENTS_DIR);
31	    return agents.map((agent) =>
32	      path.join(AGENTS_DIR, agent, 'sessions/sessions.json')
33	    );
34	  } catch {
35	    // Fallback to known paths if readdir fails
36	    return [
37	      path.join(AGENTS_DIR, 'main/sessions/sessions.json'),
38	      path.join(AGENTS_DIR, 'voice/sessions/sessions.json'),
39	      path.join(AGENTS_DIR, 'opus/sessions/sessions.json'),
40	      path.join(AGENTS_DIR, 'sonnet/sessions/sessions.json'),
41	      path.join(AGENTS_DIR, 'haiku/sessions/sessions.json'),
42	    ];
43	  }
44	}
45	
46	// Sidecar file with human-readable task descriptions keyed by label
47	const DESCRIPTIONS_FILE = path.join(process.env.HOME || '/root', '.openclaw/workspace/job-descriptions.json');
48	
49	// Only show sessions active in the last N minutes
50	const ACTIVE_MINUTES = 60;
51	
52	/** Extract a short 1-line summary from a potentially huge task prompt */
53	function extractTaskSummary(task: string): string {
54	  if (!task) return '';
55	  const lines = task.split('\n');
56	  for (const line of lines) {
57	    const trimmed = line.trim();
58	    if (!trimmed) continue;
59	    if (trimmed.startsWith('#')) continue;
60	    if (trimmed.startsWith('---')) continue;
61	    if (trimmed.startsWith('```')) continue;
62	    // Found a meaningful line — truncate to 100 chars
63	    return trimmed.length > 100 ? trimmed.slice(0, 97) + '...' : trimmed;
64	  }
65	  return '';
66	}
67	
68	async function loadDescriptions(): Promise<Record<string, string>> {
69	  try {
70	    const raw = await readFile(DESCRIPTIONS_FILE, 'utf-8');
71	    return JSON.parse(raw);
72	  } catch {
73	    return {};
74	  }
75	}
76	
77	export async function GET() {
78	  try {
79	    // Dynamically discover and read all agent session stores
80	    const sessionStorePaths = await getSessionStorePaths();
81	    const allSessions: Record<string, Record<string, unknown>> = {};
82	    for (const storePath of sessionStorePaths) {
83	      try {
84	        const raw = await readFile(storePath, 'utf-8');
85	        const store = JSON.parse(raw) as Record<string, Record<string, unknown>>;
86	        Object.assign(allSessions, store);
87	      } catch {
88	        // File might not exist, skip
89	      }
90	    }
91	
92	    const descriptions = await loadDescriptions();
93	    const now = Date.now();
94	    const cutoff = now - ACTIVE_MINUTES * 60 * 1000;
95	
96	    const jobs: ActiveJob[] = [];
97	
98	    // Recognised job kinds — extensible. Each entry maps a key substring to the
99	    // "kind" label exposed to the widget. Order matters: the first match wins.
100	    const KIND_MATCHERS: Array<{ match: string; kind: string }> = [
101	      { match: 'subagent', kind: 'subagent' },
102	      { match: 'cron', kind: 'cron' },
103	      { match: 'agent:claude-code:', kind: 'claude-code' },
104	      { match: 'agent:codex:', kind: 'codex' },
