1	import { NextRequest, NextResponse } from 'next/server';
2	import { promises as fs } from 'fs';
3	import path from 'path';
4	
5	export const dynamic = 'force-dynamic';
6	
7	const FEEDBACK_DIR = path.join(process.cwd(), '.data', 'task-feedback');
8	const FEEDBACK_FILE = path.join(FEEDBACK_DIR, 'feedback.jsonl');
9	const IMAGES_DIR = path.join(FEEDBACK_DIR, 'images');
10	
11	async function ensureDirs() {
12	  await fs.mkdir(FEEDBACK_DIR, { recursive: true });
13	  await fs.mkdir(IMAGES_DIR, { recursive: true });
14	}
15	
16	/**
17	 * Relaunch a task via the OpenClaw bot gateway with feedback context.
18	 * Sends the original task + user feedback so the agent can redo it.
19	 */
20	async function relaunchTaskWithFeedback(taskName: string, taskDescription: string, feedbackNotes: string): Promise<{ ok: boolean; error?: string }> {
21	  const botControlUrl = process.env.NEXT_PUBLIC_BOT_CONTROL_BASE_URL || 'http://localhost:4444';
22	  
23	  const relaunchPrompt = [
24	    `RELAUNCH — User gave negative feedback on task "${taskName}".`,
25	    taskDescription ? `Original task: ${taskDescription}` : '',
26	    `User feedback: ${feedbackNotes}`,
27	    `Please redo this task, addressing the user's feedback.`,
28	  ].filter(Boolean).join('\n');
29	
30	  try {
31	    // Use the bot gateway's message endpoint to trigger a new agent run
32	    const response = await fetch(`${botControlUrl}/api/message`, {
33	      method: 'POST',
34	      headers: { 'Content-Type': 'application/json' },
35	      body: JSON.stringify({
36	        message: relaunchPrompt,
37	        channel: 'task-feedback-relaunch',
38	        source: 'task-feedback',
39	      }),
40	    });
41	
42	    if (!response.ok) {
43	      const text = await response.text();
44	      console.error(`[task-feedback] Relaunch failed (${response.status}):`, text);
45	      return { ok: false, error: `Gateway returned ${response.status}` };
46	    }
47	
48	    const result = await response.json();
49	    console.log(`[task-feedback] Task relaunched:`, result);
50	    return { ok: true };
51	  } catch (error) {
52	    console.error('[task-feedback] Relaunch error:', error);
53	    return { ok: false, error: String(error) };
54	  }
55	}
56	
57	export async function POST(req: NextRequest): Promise<NextResponse> {
58	  try {
59	    await ensureDirs();
60	
61	    const contentType = req.headers.get('content-type') || '';
62	
63	    let taskId: string;
64	    let taskName: string;
65	    let type: string;
66	    let notes: string;
67	    let timestamp: string;
68	    let mode: string;
69	    let taskDescription: string;
70	    let relaunch = false;
71	    const imagePaths: string[] = [];
72	
